pub trait GqlRequestContextAttrs<'input>: GQLParserContext<'input> + BorrowMut<GqlRequestContextExt<'input>>{

fn gqlProgram(&self) -> Option<Rc<GqlProgramContextAll<'input>>> where Self:Sized{
	self.child_of_type(0)
}
/// Retrieves first TerminalNode corresponding to token EOF
/// Returns `None` if there is no child corresponding to token EOF
fn EOF(&self) -> Option<Rc<TerminalNode<'input,GQLParserContextType>>> where Self:Sized{
	self.get_token(GQL_EOF, 0)
}
/// Retrieves first TerminalNode corresponding to token SEMICOLON
/// Returns `None` if there is no child corresponding to token SEMICOLON
fn SEMICOLON(&self) -> Option<Rc<TerminalNode<'input,GQLParserContextType>>> where Self:Sized{
	self.get_token(GQL_SEMICOLON, 0)
}

}

impl<'input> GqlRequestContextAttrs<'input> for GqlRequestContext<'input>{}

impl<'input, I> GQLParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
	pub fn gqlRequest(&mut self,)
	-> Result<Rc<GqlRequestContextAll<'input>>,ANTLRError> {
		let mut recog = self;
		let _parentctx = recog.ctx.take();
		let mut _localctx = GqlRequestContextExt::new(_parentctx.clone(), recog.base.get_state());
        recog.base.enter_rule(_localctx.clone(), 0, RULE_gqlRequest);
        let mut _localctx: Rc<GqlRequestContextAll> = _localctx;
		let mut _la: i32 = -1;
		let result: Result<(), ANTLRError> = (|| {

			//recog.base.enter_outer_alt(_localctx.clone(), 1)?;
			recog.base.enter_outer_alt(None, 1)?;
			{
			/*InvokeRule gqlProgram*/
			recog.base.set_state(1028);
			recog.gqlProgram()?;

			recog.base.set_state(1030);
			recog.err_handler.sync(&mut recog.base)?;
			_la = recog.base.input.la(1);
			if _la==GQL_SEMICOLON {
				{
				recog.base.set_state(1029);
				recog.base.match_token(GQL_SEMICOLON,&mut recog.err_handler)?;

				}
			}

			recog.base.set_state(1032);
			recog.base.match_token(GQL_EOF,&mut recog.err_handler)?;

			}
			Ok(())
		})();
		match result {
		Ok(_)=>{},
        Err(e @ ANTLRError::FallThrough(_)) => return Err(e),
		Err(ref re) => {
				//_localctx.exception = re;
				recog.err_handler.report_error(&mut recog.base, re);
				recog.err_handler.recover(&mut recog.base, re)?;
			}
		}
		recog.base.exit_rule()?;

		Ok(_localctx)
	}
}
