impl<'input, I> GQLParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
	pub fn caseFunction(&mut self,)
	-> Result<Rc<CaseFunctionContextAll<'input>>,ANTLRError> {
		let mut recog = self;
		let _parentctx = recog.ctx.take();
		let mut _localctx = CaseFunctionContextExt::new(_parentctx.clone(), recog.base.get_state());
        recog.base.enter_rule(_localctx.clone(), 958, RULE_caseFunction);
        let mut _localctx: Rc<CaseFunctionContextAll> = _localctx;
		let mut _la: i32 = -1;
		let result: Result<(), ANTLRError> = (|| {

			recog.base.set_state(4124);
			recog.err_handler.sync(&mut recog.base)?;
			match  recog.interpreter.adaptive_predict(464,&mut recog.base)? {
				1 =>{
					let tmp = GqlNullIfCaseFunctionContextExt::new(&**_localctx);
					recog.base.enter_outer_alt(Some(tmp.clone()), 1)?;
					_localctx = tmp;
					{
					recog.base.set_state(4083);
					recog.base.match_token(GQL_NULLIF,&mut recog.err_handler)?;

					recog.base.set_state(4084);
					recog.base.match_token(GQL_LEFT_PAREN,&mut recog.err_handler)?;

					/*InvokeRule expression*/
					recog.base.set_state(4085);
					let tmp = recog.expression_rec(0)?;
					if let CaseFunctionContextAll::GqlNullIfCaseFunctionContext(ctx) = cast_mut::<_,CaseFunctionContextAll >(&mut _localctx){
					ctx.lhs = Some(tmp.clone()); } else {unreachable!("cant cast");}  

					recog.base.set_state(4086);
					recog.base.match_token(GQL_COMMA,&mut recog.err_handler)?;

					/*InvokeRule expression*/
					recog.base.set_state(4087);
					let tmp = recog.expression_rec(0)?;
					if let CaseFunctionContextAll::GqlNullIfCaseFunctionContext(ctx) = cast_mut::<_,CaseFunctionContextAll >(&mut _localctx){
					ctx.rhs = Some(tmp.clone()); } else {unreachable!("cant cast");}  

					recog.base.set_state(4088);
					recog.base.match_token(GQL_RIGHT_PAREN,&mut recog.err_handler)?;

					}
				}
			,
				2 =>{
					let tmp = GqlCoalesceCaseFunctionContextExt::new(&**_localctx);
					recog.base.enter_outer_alt(Some(tmp.clone()), 2)?;
					_localctx = tmp;
					{
					recog.base.set_state(4090);
					recog.base.match_token(GQL_COALESCE,&mut recog.err_handler)?;

					recog.base.set_state(4091);
					recog.base.match_token(GQL_LEFT_PAREN,&mut recog.err_handler)?;

					/*InvokeRule expression*/
					recog.base.set_state(4092);
					recog.expression_rec(0)?;

					recog.base.set_state(4095); 
					recog.err_handler.sync(&mut recog.base)?;
					_la = recog.base.input.la(1);
					loop {
						{
						{
						recog.base.set_state(4093);
						recog.base.match_token(GQL_COMMA,&mut recog.err_handler)?;

						/*InvokeRule expression*/
						recog.base.set_state(4094);
						recog.expression_rec(0)?;

						}
						}
						recog.base.set_state(4097); 
						recog.err_handler.sync(&mut recog.base)?;
						_la = recog.base.input.la(1);
						if !(_la==GQL_COMMA) {break}
					}
					recog.base.set_state(4099);
					recog.base.match_token(GQL_RIGHT_PAREN,&mut recog.err_handler)?;

					}
				}
			,
				3 =>{
					let tmp = GqlSimpleCaseFunctionContextExt::new(&**_localctx);
					recog.base.enter_outer_alt(Some(tmp.clone()), 3)?;
					_localctx = tmp;
					{
					recog.base.set_state(4101);
					recog.base.match_token(GQL_CASE,&mut recog.err_handler)?;

					/*InvokeRule expressionAtom*/
					recog.base.set_state(4102);
					recog.expressionAtom_rec(0)?;

					recog.base.set_state(4104); 
					recog.err_handler.sync(&mut recog.base)?;
					_la = recog.base.input.la(1);
					loop {
						{
						{
						/*InvokeRule simpleWhenClause*/
						recog.base.set_state(4103);
						recog.simpleWhenClause()?;

						}
						}
						recog.base.set_state(4106); 
						recog.err_handler.sync(&mut recog.base)?;
						_la = recog.base.input.la(1);
						if !(_la==GQL_WHEN) {break}
					}
					recog.base.set_state(4109);
					recog.err_handler.sync(&mut recog.base)?;
					_la = recog.base.input.la(1);
					if _la==GQL_ELSE {
						{
						/*InvokeRule elseClause*/
						recog.base.set_state(4108);
						recog.elseClause()?;

						}
					}

					recog.base.set_state(4111);
					recog.base.match_token(GQL_END,&mut recog.err_handler)?;

					}
				}
			,
				4 =>{
					let tmp = GqlSearchedCaseFunctionContextExt::new(&**_localctx);
					recog.base.enter_outer_alt(Some(tmp.clone()), 4)?;
					_localctx = tmp;
					{
					recog.base.set_state(4113);
					recog.base.match_token(GQL_CASE,&mut recog.err_handler)?;

					recog.base.set_state(4115); 
					recog.err_handler.sync(&mut recog.base)?;
					_la = recog.base.input.la(1);
					loop {
						{
						{
						/*InvokeRule searchedWhenClause*/
						recog.base.set_state(4114);
						recog.searchedWhenClause()?;

						}
						}
						recog.base.set_state(4117); 
						recog.err_handler.sync(&mut recog.base)?;
						_la = recog.base.input.la(1);
						if !(_la==GQL_WHEN) {break}
					}
					recog.base.set_state(4120);
					recog.err_handler.sync(&mut recog.base)?;
					_la = recog.base.input.la(1);
					if _la==GQL_ELSE {
						{
						/*InvokeRule elseClause*/
						recog.base.set_state(4119);
						recog.elseClause()?;

						}
					}

					recog.base.set_state(4122);
					recog.base.match_token(GQL_END,&mut recog.err_handler)?;

					}
				}

				_ => {}
			}
			Ok(())
		})();
		match result {
		Ok(_)=>{},
        Err(e @ ANTLRError::FallThrough(_)) => return Err(e),
		Err(ref re) => {
				//_localctx.exception = re;
				recog.err_handler.report_error(&mut recog.base, re);
				recog.err_handler.recover(&mut recog.base, re)?;
			}
		}
		recog.base.exit_rule()?;

		Ok(_localctx)
	}
}
