impl<'input, I> GQLParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
	pub fn recordLiteral(&mut self,)
	-> Result<Rc<RecordLiteralContextAll<'input>>,ANTLRError> {
		let mut recog = self;
		let _parentctx = recog.ctx.take();
		let mut _localctx = RecordLiteralContextExt::new(_parentctx.clone(), recog.base.get_state());
        recog.base.enter_rule(_localctx.clone(), 1024, RULE_recordLiteral);
        let mut _localctx: Rc<RecordLiteralContextAll> = _localctx;
		let mut _la: i32 = -1;
		let result: Result<(), ANTLRError> = (|| {

			//recog.base.enter_outer_alt(_localctx.clone(), 1)?;
			recog.base.enter_outer_alt(None, 1)?;
			{
			recog.base.set_state(4348);
			recog.err_handler.sync(&mut recog.base)?;
			_la = recog.base.input.la(1);
			if _la==GQL_RECORD {
				{
				recog.base.set_state(4347);
				recog.base.match_token(GQL_RECORD,&mut recog.err_handler)?;

				}
			}

			recog.base.set_state(4350);
			recog.base.match_token(GQL_LEFT_BRACE,&mut recog.err_handler)?;

			recog.base.set_state(4359);
			recog.err_handler.sync(&mut recog.base)?;
			_la = recog.base.input.la(1);
			if ((((_la - 337)) & !0x3f) == 0 && ((1usize << (_la - 337)) & 67) != 0) {
				{
				/*InvokeRule recordFieldLiteral*/
				recog.base.set_state(4351);
				recog.recordFieldLiteral()?;

				recog.base.set_state(4356);
				recog.err_handler.sync(&mut recog.base)?;
				_la = recog.base.input.la(1);
				while _la==GQL_COMMA {
					{
					{
					recog.base.set_state(4352);
					recog.base.match_token(GQL_COMMA,&mut recog.err_handler)?;

					/*InvokeRule recordFieldLiteral*/
					recog.base.set_state(4353);
					recog.recordFieldLiteral()?;

					}
					}
					recog.base.set_state(4358);
					recog.err_handler.sync(&mut recog.base)?;
					_la = recog.base.input.la(1);
				}
				}
			}

			recog.base.set_state(4361);
			recog.base.match_token(GQL_RIGHT_BRACE,&mut recog.err_handler)?;

			}
			Ok(())
		})();
		match result {
		Ok(_)=>{},
        Err(e @ ANTLRError::FallThrough(_)) => return Err(e),
		Err(ref re) => {
				//_localctx.exception = re;
				recog.err_handler.report_error(&mut recog.base, re);
				recog.err_handler.recover(&mut recog.base, re)?;
			}
		}
		recog.base.exit_rule()?;

		Ok(_localctx)
	}
}
