pub type RecordFieldLiteralContextAll<'input> = RecordFieldLiteralContext<'input>;


pub type RecordFieldLiteralContext<'input> = BaseParserRuleContext<'input,RecordFieldLiteralContextExt<'input>>;

#[derive(Clone)]
pub struct RecordFieldLiteralContextExt<'input>{
	pub key: Option<Rc<VariableContextAll<'input>>>,
	pub value: Option<Rc<GeneralLiteralContextAll<'input>>>,
ph:PhantomData<&'input str>
}

impl<'input> GQLParserContext<'input> for RecordFieldLiteralContext<'input>{}

impl<'input,'a> Listenable<dyn GQLListener<'input> + 'a> for RecordFieldLiteralContext<'input>{
		fn enter(&self,listener: &mut (dyn GQLListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.enter_every_rule(self)?;
			listener.enter_recordFieldLiteral(self);
			Ok(())
		}fn exit(&self,listener: &mut (dyn GQLListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.exit_recordFieldLiteral(self);
			listener.exit_every_rule(self)?;
			Ok(())
		}
}

impl<'input> CustomRuleContext<'input> for RecordFieldLiteralContextExt<'input>{
	type TF = LocalTokenFactory<'input>;
	type Ctx = GQLParserContextType;
	fn get_rule_index(&self) -> usize { RULE_recordFieldLiteral }
	//fn type_rule_index() -> usize where Self: Sized { RULE_recordFieldLiteral }
}
antlr4rust::tid!{RecordFieldLiteralContextExt<'a>}

impl<'input> RecordFieldLiteralContextExt<'input>{
	fn new(parent: Option<Rc<dyn GQLParserContext<'input> + 'input > >, invoking_state: i32) -> Rc<RecordFieldLiteralContextAll<'input>> {
		Rc::new(
			BaseParserRuleContext::new_parser_ctx(parent, invoking_state,RecordFieldLiteralContextExt{
				key: None, value: None, 

				ph:PhantomData
			}),
		)
	}
}

pub trait RecordFieldLiteralContextAttrs<'input>: GQLParserContext<'input> + BorrowMut<RecordFieldLiteralContextExt<'input>>{

/// Retrieves first TerminalNode corresponding to token COLON
/// Returns `None` if there is no child corresponding to token COLON
fn COLON(&self) -> Option<Rc<TerminalNode<'input,GQLParserContextType>>> where Self:Sized{
	self.get_token(GQL_COLON, 0)
}
fn variable(&self) -> Option<Rc<VariableContextAll<'input>>> where Self:Sized{
	self.child_of_type(0)
}
fn generalLiteral(&self) -> Option<Rc<GeneralLiteralContextAll<'input>>> where Self:Sized{
	self.child_of_type(0)
}

}

